import re

_NUMBER_RE = re.compile(r"-?\d+", re.ASCII)


class StackUnderflowError(Exception):
    pass


def _check_stack(stack, count):
    if len(stack) < count:
        raise StackUnderflowError("Insufficient number of items in stack")


def _add(stack):
    _check_stack(stack, 2)
    b = stack.pop()
    a = stack.pop()
    stack.append(a + b)


def _sub(stack):
    _check_stack(stack, 2)
    b = stack.pop()
    a = stack.pop()
    stack.append(a - b)


def _mul(stack):
    _check_stack(stack, 2)
    b = stack.pop()
    a = stack.pop()
    stack.append(a * b)


def _div(stack):
    _check_stack(stack, 2)
    b = stack.pop()
    a = stack.pop()
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    quotient = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        quotient = -quotient
    stack.append(quotient)


def _dup(stack):
    _check_stack(stack, 1)
    stack.append(stack[-1])


def _drop(stack):
    _check_stack(stack, 1)
    stack.pop()


def _swap(stack):
    _check_stack(stack, 2)
    stack[-1], stack[-2] = stack[-2], stack[-1]


def _over(stack):
    _check_stack(stack, 2)
    stack.append(stack[-2])


_BUILTINS = {
    "+": _add,
    "-": _sub,
    "*": _mul,
    "/": _div,
    "dup": _dup,
    "drop": _drop,
    "swap": _swap,
    "over": _over,
}


def _tokenize(line):
    for token in line.split():
        if _NUMBER_RE.fullmatch(token):
            yield ("number", int(token))
        else:
            yield ("word", token.lower())


def _run(body, stack):
    for kind, value in body:
        if kind == "number":
            stack.append(value)
        else:
            _BUILTINS[value](stack)


def evaluate(input_data):
    stack = []
    words = {}
    state = None  # None, "name" or "body"
    name = None
    definition = []

    for line in input_data:
        for kind, value in _tokenize(line):
            if state == "name":
                if kind == "number":
                    raise ValueError("illegal operation")
                name = value
                state = "body"
            elif state == "body":
                if kind == "word" and value == ";":
                    body = []
                    for def_kind, def_value in definition:
                        if def_kind == "number":
                            body.append(("number", def_value))
                        elif def_value in words:
                            # Inline the current definition so that later
                            # redefinitions do not affect this word.
                            body.extend(words[def_value])
                        elif def_value in _BUILTINS:
                            body.append(("builtin", def_value))
                        else:
                            raise ValueError("undefined operation")
                    words[name] = body
                    state = None
                    definition = []
                else:
                    definition.append((kind, value))
            else:
                if kind == "number":
                    stack.append(value)
                elif value == ":":
                    state = "name"
                elif value in words:
                    _run(words[value], stack)
                elif value in _BUILTINS:
                    _BUILTINS[value](stack)
                else:
                    raise ValueError("undefined operation")

    return stack
